# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "3.1.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v3.1.0/dedup-3.1.0-macos-arm64.tar.gz"
      sha256 "36ffe7c513f731b9417c4aa63af3b567c1472cfe5724e930f53593aae6dc3b1d"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v3.1.0/dedup-3.1.0-macos-x86_64.tar.gz"
      sha256 "6e0a34b25444c6202dc826c3a7ed711439fea00bca0440c1f1009a2dc029b002"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v3.1.0/dedup-3.1.0-linux-x86_64.tar.gz"
    sha256 "9dbb31ef8a07225f3ea83d21bd3ce3c3eb7c2ad4bdfa1f5ad7ed0bd511801bc8"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
